/* stack.h: public interface. */
#ifndef STACK_H
#define STACK_H
#include <stdbool.h>
#include <stddef.h>

typedef struct Stack Stack;          /* opaque: layout hidden. */

/* Returns NULL on allocation failure. Caller owns the stack; free with stack_destroy. */
Stack *stack_create(void);
void   stack_destroy(Stack *s);      /* accepts NULL. */
bool   stack_push(Stack *s, int v);  /* false on allocation failure. */
bool   stack_pop(Stack *s, int *out);/* false if empty. */
size_t stack_size(const Stack *s);
#endif
```

