/* stack.c: private implementation. */
#include "stack.h"
#include <stdlib.h>

struct Stack { int *items; size_t len, cap; };   /* only this file sees fields. */

static bool grow(Stack *s) {                     /* private helper. */
    size_t cap = s->cap ? s->cap * 2 : 8;
    int *p = realloc(s->items, cap * sizeof *p);
    if (!p) return false;
    s->items = p; s->cap = cap;
    return true;
}
/* ... stack_create, stack_push (calls grow), etc. ... */
